'use client';

import { createContext, useContext, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { User, Session } from '@supabase/supabase-js';

type AuthContextType = {
    user: User | null;
    session: Session | null;
    loading: boolean;
};

const AuthContext = createContext<AuthContextType>({
    user: null,
    session: null,
    loading: true,
});

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Session 取得
        const getSession = async () => {
            // --- DEV MODE BYPASS ---
            if (typeof window !== 'undefined' && localStorage.getItem('dev_mock_session') === 'true') {
                const mockUser = {
                    id: 'dev-mock-uuid-1234-5678',
                    email: 'test@test.com',
                    app_metadata: {},
                    user_metadata: {},
                    aud: 'authenticated',
                    created_at: new Date().toISOString(),
                } as User;

                setSession({ access_token: 'mock', refresh_token: 'mock', expires_in: 3600, token_type: 'bearer', user: mockUser });
                setUser(mockUser);
                setLoading(false);
                return;
            }
            // ------------------------

            const { data: { session }, error } = await supabase.auth.getSession();
            if (!error) {
                setSession(session);
                setUser(session?.user ?? null);
            }
            setLoading(false);
        };

        getSession();

        // Session 変更のリスナー設定
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            (_event, session) => {
                // If we are in dev mock mode, ignore real auth state changes that might reset it
                if (typeof window !== 'undefined' && localStorage.getItem('dev_mock_session') === 'true') {
                    return;
                }

                setSession(session);
                setUser(session?.user ?? null);

                // ログイン時に users テーブルにレコードがなければ作成 (または更新)
                if (session?.user) {
                    upsertUser(session.user);
                }
            }
        );

        // Custom event listener for dev mock login
        const handleMockLogin = () => {
            getSession();
        };
        if (typeof window !== 'undefined') {
            window.addEventListener('dev_mock_login', handleMockLogin);
        }

        return () => {
            subscription.unsubscribe();
            if (typeof window !== 'undefined') {
                window.removeEventListener('dev_mock_login', handleMockLogin);
            }
        };
    }, []);

    const upsertUser = async (authUser: User) => {
        try {
            // ユーザーのプロファイルが作られているか確認、なければ作成
            await supabase.from('users').upsert({
                id: authUser.id,
                // Authから名前が取得できる場合は設定（例：Googleログイン時など）
                // Magic Linkの場合はあとからプロフィール設定画面で編集させる想定
                updated_at: new Date().toISOString()
            }, { onConflict: 'id' });
        } catch (e) {
            console.error('Error upserting user profile:', e);
        }
    };

    return (
        <AuthContext.Provider value={{ user, session, loading }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    return useContext(AuthContext);
};

"use client";

import { useDisasterAlerts, DisasterAlert } from "@/hooks/useDisasterAlerts";
import { AlertTriangle, Info, Bell, AlertOctagon } from "lucide-react";
import { WeeklyForecast } from "./WeeklyForecast";

export function DisasterAlertBanner() {
    const { alerts, forecast, weeklyForecast, locationName, loading, error, refetch } = useDisasterAlerts();

    if (loading) {
        return (
            <div className="bg-slate-50 text-slate-500 text-xs py-2 px-4 shadow flex items-center justify-between border-b border-slate-200">
                <span>現在地の災害情報を取得中...</span>
            </div>
        );
    }

    if (error || !locationName) {
        return null; // Don't show anything if it fails or there's no location
    }

    if (alerts.length === 0) {
        return (
            <div className="bg-teal-50 text-teal-800 text-xs py-2.5 px-4 shadow flex flex-col gap-1.5 border-b border-teal-100">
                <div className="flex items-center gap-2">
                    <Info size={14} className="text-teal-600 flex-shrink-0" />
                    <span className="leading-tight">
                        <strong>{locationName}</strong>: 現在発表されている気象警報・注意報はありません。
                    </span>
                    <button onClick={refetch} className="ml-auto flex-shrink-0 underline text-[10px] text-teal-600">更新</button>
                </div>
                {forecast && (
                    <div className="flex items-center gap-1.5 ml-5 text-slate-600 font-medium">
                        <span className="text-[10px] bg-white text-teal-700 px-1.5 py-0.5 rounded border border-teal-200">今日の天気</span>
                        <span className="truncate">{forecast.weather}</span>
                    </div>
                )}

                {/* 週間天気予報 */}
                {weeklyForecast && weeklyForecast.length > 0 && (
                    <div className="ml-5 mt-1">
                        <WeeklyForecast forecasts={weeklyForecast} />
                    </div>
                )}
            </div>
        );
    }

    // Sort alerts by severity (emergency > warning > advisory)
    const sortedAlerts = [...alerts].sort((a, b) => {
        const severityScores = { emergency: 3, warning: 2, advisory: 1 };
        return severityScores[b.level] - severityScores[a.level];
    });

    const getColorsByLevel = (level: 'emergency' | 'warning' | 'advisory') => {
        switch (level) {
            case 'emergency':
                return 'bg-purple-600 text-white border-purple-800'; // Special Warning
            case 'warning':
                return 'bg-red-500 text-white border-red-700';       // Warning
            case 'advisory':
                return 'bg-yellow-100 text-yellow-800 border-yellow-300'; // Advisory
        }
    };

    const getIconByLevel = (level: 'emergency' | 'warning' | 'advisory') => {
        switch (level) {
            case 'emergency': return <AlertOctagon size={18} />;
            case 'warning': return <AlertTriangle size={18} />;
            case 'advisory': return <Bell size={18} />;
        }
    };

    // Grab the highest severity alert to determine the banner color
    const highestLevel = sortedAlerts[0].level;
    const bannerClasses = getColorsByLevel(highestLevel);

    return (
        <div className={`py-3 px-4 shadow-md flex items-start gap-3 border-b ${bannerClasses}`}>
            <div className="mt-0.5">
                {getIconByLevel(highestLevel)}
            </div>
            <div className="flex-1">
                <div className="flex items-start justify-between mb-1.5">
                    <div>
                        <span className="text-xs font-bold opacity-90 block">{locationName}の気象情報</span>
                        {forecast && (
                            <span className="text-[11px] opacity-90 block mt-0.5">
                                天気: {forecast.weather}
                            </span>
                        )}
                    </div>
                    <button onClick={refetch} className="text-[10px] underline opacity-80 hover:opacity-100 flex-shrink-0">更新</button>
                </div>
                <div className="flex flex-wrap gap-1.5">
                    {sortedAlerts.map((alert) => (
                        <span
                            key={alert.code}
                            className={`text-sm font-bold px-2 py-0.5 rounded ${alert.level === 'emergency' ? 'bg-purple-800 text-white' :
                                alert.level === 'warning' ? 'bg-red-700 text-white' :
                                    'bg-yellow-200 text-yellow-900 border border-yellow-400'
                                }`}
                        >
                            {alert.label}
                        </span>
                    ))}
                </div>

                {/* 週間天気予報 */}
                {weeklyForecast && weeklyForecast.length > 0 && (
                    <WeeklyForecast forecasts={weeklyForecast} />
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { CheckCircle, AlertTriangle, HelpCircle, Send, Loader2 } from "lucide-react";
import { supabase } from "@/lib/supabase";
import { useAuth } from "@/components/Auth/AuthProvider";
import { useGeolocation } from "react-use";

export function StatusForm() {
    const { user } = useAuth();
    const [status, setStatus] = useState<"safe" | "danger" | "unknown">("safe");
    const [message, setMessage] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [feedback, setFeedback] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

    // Get current location when submitting
    const currentLocation = useGeolocation({ enableHighAccuracy: true });

    // Handle DevMode
    const isDevMode = typeof window !== 'undefined' && localStorage.getItem('dev_mock_session') === 'true';

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) {
            setFeedback({ text: 'ログインが必要です', type: 'error' });
            return;
        }

        setIsSubmitting(true);
        setFeedback(null);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            setTimeout(() => {
                // Save mock data so useFamilyLocation can read it
                localStorage.setItem('dev_mock_status', status);
                localStorage.setItem('dev_mock_message', message);
                localStorage.setItem('dev_mock_updated_at', Date.now().toString());

                setFeedback({ text: `[DevMode] ステータスを更新しました！`, type: 'success' });
                setMessage("");
                setIsSubmitting(false);
                // We will mock firing an event so other components know data "changed"
                window.dispatchEvent(new Event('dev_mock_status_update'));
            }, 800);
            return;
        }
        // ------------------------

        try {
            const { error } = await supabase
                .from('safety_status')
                .upsert({
                    user_id: user.id,
                    status: status,
                    message: message || null,
                    latitude: currentLocation.latitude || null,
                    longitude: currentLocation.longitude || null,
                    updated_at: new Date().toISOString()
                }, { onConflict: 'user_id' });

            if (error) throw error;

            setFeedback({ text: '安否状況を家族に共有しました！', type: 'success' });
            setMessage(""); // Clear message after success
        } catch (err: any) {
            console.error('Error saving status:', err);
            setFeedback({ text: '送信に失敗しました。時間をおいて再試行してください。', type: 'error' });
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 text-slate-800">安否報告</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-3 gap-3">
                    <button
                        type="button"
                        onClick={() => setStatus("safe")}
                        className={`p-3 rounded-lg flex flex-col items-center justify-center border-2 transition-all ${status === "safe"
                            ? "border-green-500 bg-green-50 text-green-700"
                            : "border-slate-200 hover:border-green-200 text-slate-500"
                            }`}
                    >
                        <CheckCircle className="w-6 h-6 mb-1" />
                        <span className="text-xs font-bold">無事</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => setStatus("danger")}
                        className={`p-3 rounded-lg flex flex-col items-center justify-center border-2 transition-all ${status === "danger"
                            ? "border-red-500 bg-red-50 text-red-700"
                            : "border-slate-200 hover:border-red-200 text-slate-500"
                            }`}
                    >
                        <AlertTriangle className="w-6 h-6 mb-1" />
                        <span className="text-xs font-bold">SOS</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => setStatus("unknown")}
                        className={`p-3 rounded-lg flex flex-col items-center justify-center border-2 transition-all ${status === "unknown"
                            ? "border-yellow-500 bg-yellow-50 text-yellow-700"
                            : "border-slate-200 hover:border-yellow-200 text-slate-500"
                            }`}
                    >
                        <HelpCircle className="w-6 h-6 mb-1" />
                        <span className="text-xs font-bold">不明・移動中</span>
                    </button>
                </div>

                <textarea
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="今の状況や、これから向かう場所を入力... (任意)"
                    className="w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-cyan-500 focus:border-transparent text-sm min-h-[100px]"
                />

                {feedback && (
                    <div className={`p-3 rounded-lg text-sm ${feedback.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                        {feedback.text}
                    </div>
                )}

                <button
                    type="submit"
                    disabled={isSubmitting || !user}
                    className="w-full bg-cyan-600 hover:bg-cyan-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 shadow-sm transition-all disabled:opacity-50"
                >
                    {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
                    {isSubmitting ? '送信中...' : '状況を送信'}
                </button>
            </form>
        </div>
    );
}

