"use client";

import { useEffect, useState } from "react";
import { APIProvider, useMapsLibrary } from "@vis.gl/react-google-maps";
import { useFamilyLocation } from "@/hooks/useFamilyLocation";
import { Shelter } from "@/types/shelter";
import { MapPin, Plus, Loader2, ShieldCheck } from "lucide-react";
import { fetchGSIShelters } from "@/services/gsiShelterService";

const API_KEY = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY || "";

interface NearbySheltersProps {
    onAdd: (shelter: Omit<Shelter, 'id' | 'createdAt'>) => void;
}

// Haversine formula to calculate distance between two points
function calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): string {
    const R = 6371; // Radius of the earth in km
    const dLat = deg2rad(lat2 - lat1);
    const dLon = deg2rad(lon2 - lon1);
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
        Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const d = R * c; // Distance in km

    if (d < 1) {
        return `${Math.round(d * 1000)}m`;
    }
    return `${d.toFixed(1)}km`;
}

function deg2rad(deg: number) {
    return deg * (Math.PI / 180);
}

function NearbySheltersContent({ onAdd }: NearbySheltersProps) {
    const placesLib = useMapsLibrary('places');
    const { currentLocation } = useFamilyLocation();
    const [nearbyPlaces, setNearbyPlaces] = useState<google.maps.places.PlaceResult[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [searchStatus, setSearchStatus] = useState<string>("");
    const [customQuery, setCustomQuery] = useState("");

    // Timeout handling for location loading
    const [locationTimeout, setLocationTimeout] = useState(false);

    // Auto-search when location becomes available (or fails)
    useEffect(() => {
        const hasLocation = currentLocation.latitude && currentLocation.longitude;
        const hasError = currentLocation.error || locationTimeout;

        if ((hasLocation || hasError) && !nearbyPlaces.length && !isLoading && placesLib) {
            handleSearch("");
        }
    }, [currentLocation, placesLib, locationTimeout]);

    useEffect(() => {
        let timer: NodeJS.Timeout;
        if (!currentLocation.latitude && !currentLocation.error && !locationTimeout) {
            timer = setTimeout(() => {
                setLocationTimeout(true);
            }, 5000); // Reduce timeout to 5 seconds for better UX
        }
        return () => clearTimeout(timer);
    }, [currentLocation, locationTimeout]);

    const handleSearch = async (query: string) => {
        setIsLoading(true);
        setSearchStatus("検索中...");
        setNearbyPlaces([]);

        let gsiShelters: Omit<Shelter, 'id' | 'createdAt'>[] = [];

        // 1. Fetch from GSI (Official Data)
        if (currentLocation.latitude && currentLocation.longitude) {
            try {
                gsiShelters = await fetchGSIShelters(currentLocation.latitude, currentLocation.longitude);
                console.log("[Debug] GSI Shelters found:", gsiShelters.length);
            } catch (e) {
                console.error("[Debug] GSI fetch failed:", e);
            }
        }

        // Prepare GSI results as PlaceResult
        const mappedGSI = gsiShelters.map(s => ({
            name: s.name,
            vicinity: s.address || "住所不明",
            geometry: {
                location: new google.maps.LatLng(s.latitude!, s.longitude!)
            },
            place_id: `gsi-${s.name}-${s.latitude}-${s.longitude}`,
            rating: 5,
            user_ratings_total: 0,
            icon: "https://maps.google.com/mapfiles/ms/icons/blue-dot.png",
            types: ["gsi_shelter"] // Mark as official
        })) as unknown as google.maps.places.PlaceResult[];

        // If Google Maps API is not loaded, show only GSI data
        if (!placesLib) {
            if (mappedGSI.length > 0) {
                setNearbyPlaces(mappedGSI);
                setIsLoading(false);
                setSearchStatus(`国土地理院データ: ${gsiShelters.length}件が見つかりました`);
            } else {
                setIsLoading(false);
                setSearchStatus("Google Maps Placesライブラリが読み込まれていません。");
            }
            return;
        }

        // 2. Google Maps Search
        const mapDiv = document.createElement('div');
        const service = new placesLib.PlacesService(mapDiv);

        let searchQuery = query;
        const keywords = ["避難所", "避難場所", "学校", "公民館", "公園", "広域避難場所", "センター", "会館"];
        const hasKeyword = keywords.some(k => query.includes(k));

        if (!hasKeyword) {
            if (!currentLocation.latitude) {
                searchQuery = query ? `${query} 避難所` : "避難所";
            } else {
                // Hybrid search query
                searchQuery = `${query} 避難所 OR 避難場所 OR 学校 OR 公民館 OR "指定緊急避難場所"`;
            }
        }

        const request: google.maps.places.TextSearchRequest = {
            query: searchQuery,
        };

        if (currentLocation.latitude && currentLocation.longitude) {
            request.location = new google.maps.LatLng(currentLocation.latitude, currentLocation.longitude);
            request.radius = 5000;
        }

        console.log("[Debug] request:", request);

        service.textSearch(request, (results, status) => {
            console.log("[Debug] status:", status);
            console.log("[Debug] results:", results?.length);

            setIsLoading(false);

            let combinedResults: google.maps.places.PlaceResult[] = [...mappedGSI];

            if (status === placesLib.PlacesServiceStatus.OK && results) {
                // Merge strategies:
                // We want to avoid duplicates. Simple name/distance dedupe?
                // For now, let's just append Google results that are NOT roughly in the same spot as GSI results.

                const gsiLocations = mappedGSI.map(g => ({
                    lat: g.geometry?.location?.lat() || 0,
                    lng: g.geometry?.location?.lng() || 0,
                    name: g.name
                }));

                const uniqueGoogleResults = results.filter(g => {
                    const gLat = g.geometry?.location?.lat() || 0;
                    const gLng = g.geometry?.location?.lng() || 0;

                    // Check if close to any GSI result (within ~50m)
                    const isDuplicate = gsiLocations.some(official => {
                        const d = Math.sqrt(Math.pow(official.lat - gLat, 2) + Math.pow(official.lng - gLng, 2));
                        return d < 0.0005; // Roughly 50m
                    });
                    return !isDuplicate;
                });

                combinedResults = [...combinedResults, ...uniqueGoogleResults];
            } else {
                console.warn("[Debug] Google Search failed or empty:", status);
            }

            // Sort by distance
            if (combinedResults.length > 0 && currentLocation.latitude && currentLocation.longitude) {
                try {
                    const userPos = new google.maps.LatLng(currentLocation.latitude, currentLocation.longitude);
                    combinedResults.sort((a, b) => {
                        if (!a.geometry?.location || !b.geometry?.location) return 0;
                        if (!google.maps.geometry) return 0; // Should be checked earlier
                        const distA = google.maps.geometry.spherical.computeDistanceBetween(userPos, a.geometry.location);
                        const distB = google.maps.geometry.spherical.computeDistanceBetween(userPos, b.geometry.location);
                        return distA - distB;
                    });
                } catch (e) {
                    console.error("[Debug] Sort error:", e);
                }
                setNearbyPlaces(combinedResults);
                const googleCount = combinedResults.length - mappedGSI.length;
                setSearchStatus(`${combinedResults.length}件が見つかりました (公認: ${mappedGSI.length}件, その他: ${googleCount}件)`);
            } else if (mappedGSI.length > 0) {
                setNearbyPlaces(mappedGSI);
                setSearchStatus(`国土地理院データ: ${mappedGSI.length}件が見つかりました`);
            } else {
                if (request.location && status !== placesLib.PlacesServiceStatus.OK && status !== placesLib.PlacesServiceStatus.ZERO_RESULTS) {
                    setSearchStatus(`検索エラー: ${status}`);
                } else {
                    setSearchStatus("候補が見つかりませんでした");
                }
            }
        });
    };

    const handleManualSearch = (e: React.FormEvent) => {
        e.preventDefault();
        handleSearch(customQuery);
    };

    return (
        <div className="space-y-4">
            {/* Search Input Area */}
            <div className="bg-white/80 backdrop-blur-sm p-3 rounded-xl border border-cyan-100 shadow-sm">
                <form onSubmit={handleManualSearch} className="flex gap-2">
                    <input
                        type="text"
                        value={customQuery}
                        onChange={(e) => setCustomQuery(e.target.value)}
                        placeholder="地名や施設名で検索 (例: 新宿区 避難所)"
                        className="flex-1 p-3 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 outline-none transition-all placeholder:text-slate-400"
                    />
                    <button
                        type="submit"
                        disabled={isLoading || !placesLib}
                        className="bg-cyan-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-cyan-700 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap shadow-sm transition-colors"
                    >
                        検索
                    </button>
                </form>
                {!currentLocation.latitude && !currentLocation.error && !locationTimeout && (
                    <p className="text-xs text-cyan-600 mt-2 flex items-center font-medium">
                        <Loader2 className="w-3 h-3 animate-spin mr-1" />
                        現在地を取得中... (手動検索も可能です)
                    </p>
                )}
                {!currentLocation.latitude && !currentLocation.error && locationTimeout && (
                    <p className="text-xs text-slate-500 mt-2">
                        位置情報を取得できませんでした (距離を表示するには位置情報が必要です)
                    </p>
                )}
                {currentLocation.error && (
                    <p className="text-xs text-red-500 mt-2">
                        位置情報を取得できませんでした: {currentLocation.error.message || "ブラウザの設定を確認してください"}
                    </p>
                )}
            </div>

            <p className="text-sm text-slate-600 text-center min-h-[20px] font-medium">{searchStatus}</p>

            {isLoading && (
                <div className="flex justify-center p-8">
                    <Loader2 className="w-8 h-8 animate-spin text-cyan-500" />
                </div>
            )}

            <div className="space-y-3 max-h-96 overflow-y-auto pr-1 safe-scrollbar">
                {nearbyPlaces.map((place) => {
                    const isOfficial = place.types?.includes("gsi_shelter");
                    let distanceStr = "";
                    if (currentLocation.latitude && currentLocation.longitude && place.geometry?.location) {
                        distanceStr = calculateDistance(
                            currentLocation.latitude,
                            currentLocation.longitude,
                            place.geometry.location.lat(),
                            place.geometry.location.lng()
                        );
                    }

                    return (
                        <div key={place.place_id} className={`border p-4 rounded-xl flex justify-between items-start shadow-sm hover:shadow-md transition-all ${isOfficial ? "bg-cyan-50/50 border-cyan-200" : "bg-white border-slate-100 hover:border-cyan-100"}`}>
                            <div className="flex-1 min-w-0 mr-3">
                                <div className="flex flex-wrap gap-2 items-center mb-1">
                                    {isOfficial && (
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-cyan-600 text-white shadow-sm shrink-0">
                                            <ShieldCheck className="w-3 h-3 mr-0.5" />
                                            指定避難所
                                        </span>
                                    )}
                                    <h3 className="font-bold text-slate-800 text-sm truncate flex-1">{place.name}</h3>
                                </div>
                                <div className="flex justify-between items-center mb-1">
                                    {distanceStr && (
                                        <span className="text-[10px] font-bold text-cyan-700 bg-cyan-100/50 px-2 py-0.5 rounded-full whitespace-nowrap">
                                            {distanceStr}
                                        </span>
                                    )}
                                </div>
                                <p className="text-xs text-slate-500 flex items-start break-words leading-relaxed">
                                    <MapPin className="w-3.5 h-3.5 mt-0.5 mr-1.5 shrink-0 text-slate-400" />
                                    <span className="line-clamp-2">{place.formatted_address || place.vicinity}</span>
                                </p>
                            </div>
                            <button
                                onClick={() => onAdd({
                                    name: place.name || "",
                                    address: place.formatted_address || place.vicinity || "",
                                    note: isOfficial ? "【国土地理院公認】指定緊急避難場所/避難所" : `周辺検索から追加${distanceStr ? ` (距離: ${distanceStr})` : ""}`,
                                    latitude: place.geometry?.location?.lat(),
                                    longitude: place.geometry?.location?.lng(),
                                })}
                                className={`p-2.5 rounded-full shrink-0 transition-colors mt-0.5 ${isOfficial ? "bg-cyan-600 text-white hover:bg-cyan-700 shadow-sm" : "bg-cyan-50 text-cyan-600 hover:bg-cyan-100"}`}
                                title="リストに追加"
                            >
                                <Plus className="w-5 h-5" />
                            </button>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

const LIBRARIES: ("places" | "drawing" | "geometry" | "localContext" | "visualization")[] = ['places', 'geometry'];

export function NearbyShelters({ onAdd }: NearbySheltersProps) {
    return (
        <APIProvider apiKey={API_KEY} libraries={LIBRARIES}>
            <NearbySheltersContent onAdd={onAdd} />
        </APIProvider>
    );
}

"use client";

import { useState, useEffect, useCallback } from 'react';
import { useGeolocation } from 'react-use';

// This API URL provides a mapping from points to area codes
const REVERSE_GEOCODE_API = 'https://mreversegeocoder.gsi.go.jp/reverse-geocoder/LonLatToAddress';

// JMA Warning Code Definitions (simplified)
const WARNING_CODES: Record<string, { label: string; level: 'warning' | 'advisory' | 'emergency' }> = {
    // Emergency
    '03': { label: '大雨特別警報', level: 'emergency' },
    '04': { label: '大雪特別警報', level: 'emergency' },
    '05': { label: '暴風特別警報', level: 'emergency' },
    '08': { label: '高潮特別警報', level: 'emergency' },
    '09': { label: '波浪特別警報', level: 'emergency' },
    '32': { label: '暴風雪特別警報', level: 'emergency' },

    // Warning
    '10': { label: '大雨警報', level: 'warning' },
    '12': { label: '大雪警報', level: 'warning' },
    '13': { label: '暴風警報', level: 'warning' },
    '15': { label: '波浪警報', level: 'warning' },
    '16': { label: '高潮警報', level: 'warning' },
    '33': { label: '暴風雪警報', level: 'warning' },
    '35': { label: '洪水警報', level: 'warning' },

    // Advisory (Notice)
    '14': { label: '大雨注意報', level: 'advisory' },
    '17': { label: '大雪注意報', level: 'advisory' },
    '18': { label: '風雪注意報', level: 'advisory' },
    '19': { label: '雷注意報', level: 'advisory' },
    '20': { label: '強風注意報', level: 'advisory' },
    '21': { label: '波浪注意報', level: 'advisory' },
    '22': { label: '融雪注意報', level: 'advisory' },
    '23': { label: '濃霧注意報', level: 'advisory' },
    '24': { label: '乾燥注意報', level: 'advisory' },
    '25': { label: 'なだれ注意報', level: 'advisory' },
    '31': { label: '着氷注意報', level: 'advisory' },
    '36': { label: '洪水注意報', level: 'advisory' },
};

// Simplified Prefecture Mapping (first 2 digits of city code)
const PREF_MAPPING: Record<string, string> = {
    '01': '北海道', '02': '青森県', '03': '岩手県', '04': '宮城県', '05': '秋田県',
    '06': '山形県', '07': '福島県', '08': '茨城県', '09': '栃木県', '10': '群馬県',
    '11': '埼玉県', '12': '千葉県', '13': '東京都', '14': '神奈川県', '15': '新潟県',
    '16': '富山県', '17': '石川県', '18': '福井県', '19': '山梨県', '20': '長野県',
    '21': '岐阜県', '22': '静岡県', '23': '愛知県', '24': '三重県', '25': '滋賀県',
    '26': '京都府', '27': '大阪府', '28': '兵庫県', '29': '奈良県', '30': '和歌山県',
    '31': '鳥取県', '32': '島根県', '33': '岡山県', '34': '広島県', '35': '山口県',
    '36': '徳島県', '37': '香川県', '38': '愛媛県', '39': '高知県', '40': '福岡県',
    '41': '佐賀県', '42': '長崎県', '43': '熊本県', '44': '大分県', '45': '宮崎県',
    '46': '鹿児島県', '47': '沖縄県'
};

export interface DisasterAlert {
    code: string;
    label: string;
    level: 'warning' | 'advisory' | 'emergency';
    areaName: string;
}

export interface WeatherForecast {
    areaName: string;
    weather: string;
}

export interface DailyForecast {
    date: string;
    weatherCode: string;
    minTemp: string; // temperature might be empty
    maxTemp: string;
}

export function useDisasterAlerts() {
    const currentLocation = useGeolocation({
        enableHighAccuracy: false,
        timeout: 30000,
        maximumAge: 300000
    });

    const [alerts, setAlerts] = useState<DisasterAlert[]>([]);
    const [forecast, setForecast] = useState<WeatherForecast | null>(null);
    const [weeklyForecast, setWeeklyForecast] = useState<DailyForecast[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [locationName, setLocationName] = useState<string | null>(null);

    const checkAlerts = useCallback(async () => {
        if (!currentLocation.latitude || !currentLocation.longitude) return;

        setLoading(true);
        setError(null);

        try {
            // 1. Convert Lat/Lng to JMA area code using GSI API
            // The GSI API takes lat/lon and returns a custom code. We need the first 2 digits for prefecture and 5 for city.
            const gsiRes = await fetch(`${REVERSE_GEOCODE_API}?lat=${currentLocation.latitude}&lon=${currentLocation.longitude}`);
            if (!gsiRes.ok) throw new Error('Failed to reverse geocode');

            const gsiData = await gsiRes.json();

            // GSI returns results like { results: { muniCd: "13101", lv01Nm: "千代田区" } }
            if (!gsiData.results || !gsiData.results.muniCd) {
                throw new Error('Could not determine municipality code');
            }

            const muniCd = gsiData.results.muniCd as string; // 5 digit City Code (e.g. 13101)
            const municipalityName = gsiData.results.lv01Nm as string; // City Name (e.g. 千代田区)

            // For JMA Warning API, we need the "Center" (Office) code which is usually a 6-digit number mapped to prefectures.
            // A simple approximation for JMA Area Code mapping:
            // JMA Prefecture Code = First 2 digits of muniCd + '0000'
            const prefId = muniCd.substring(0, 2);
            const prefCode = prefId + '0000';
            const prefName = PREF_MAPPING[prefId] || '';

            // 2. We don't have the prefecture names directly from GSI without a lookup table, 
            // so we'll fetch the JMA warning JSON for that prefecture and extract info
            const jmaUrl = `https://www.jma.go.jp/bosai/warning/data/warning/${prefCode}.json`;
            const jmaRes = await fetch(jmaUrl);

            if (!jmaRes.ok) {
                // For Hokkaido, codes are split differently, etc. Fallback to empty if it 404s
                // But we can at least show the location
                setLocationName(`${prefName}${municipalityName}`);
                setAlerts([]);
                return;
            }

            const areaWarnings = await jmaRes.json();
            // JMA format: [ { areaTypes: [ { area: { code: '1310100', name: '千代田区' }, warnings: [ { code: '10', status: '発表' } ]} ] } ]
            // Note: JMA municipality code is 7 digits (5 digit muni + '00')
            const targetJmaCode = muniCd + '00';

            const activeAlerts: DisasterAlert[] = [];
            let foundAreaName = municipalityName;

            // Traverse the messy JMA JSON structure structure to find our municipality's warnings
            for (const timeSeries of areaWarnings.timeSeries || []) {
                for (const areaType of timeSeries.areas || []) {
                    if (areaType.area && areaType.area.code === targetJmaCode) {
                        if (!foundAreaName) foundAreaName = areaType.area.name;

                        // Look at warnings
                        for (const w of areaType.warnings || []) {
                            // status: '発表' or '継続' means active. '解除' means removed.
                            if ((w.status === '発表' || w.status === '継続' || w.status === '') && WARNING_CODES[w.code]) {
                                // Add if not already there and if it's not a "00" (which means no warning sometimes)
                                if (!activeAlerts.some(a => a.code === w.code)) {
                                    activeAlerts.push({
                                        code: w.code,
                                        label: WARNING_CODES[w.code].label,
                                        level: WARNING_CODES[w.code].level,
                                        areaName: foundAreaName
                                    });
                                }
                            }
                        }
                    }
                }
            }

            // GSI's lv01Nm doesn't include the prefecture, but jmaUrl gives us the prefecture name in forecast data usually.
            // For warning alerts, the JMA area name is often just the city. 
            // We combine them for a specific explicit location (e.g. 東京都千代田区)
            const fullLocationName = `${prefName}${foundAreaName}`;

            setLocationName(fullLocationName);
            setAlerts(activeAlerts);

            // 3. Fetch weather forecast for the prefecture
            try {
                const forecastUrl = `https://www.jma.go.jp/bosai/forecast/data/forecast/${prefCode}.json`;
                const forecastRes = await fetch(forecastUrl);
                if (forecastRes.ok) {
                    const forecastData = await forecastRes.json();
                    if (forecastData && forecastData.length > 0) {
                        // --- Short Term Forecast (Today) ---
                        const shortTerm = forecastData[0];
                        const tsWeathers = shortTerm.timeSeries.find((ts: any) => ts.areas && ts.areas.length > 0 && ts.areas[0].weathers);
                        if (tsWeathers && tsWeathers.areas && tsWeathers.areas.length > 0) {
                            const area = tsWeathers.areas[0];
                            if (area.weathers && area.weathers.length > 0) {
                                setForecast({
                                    areaName: area.area.name,
                                    weather: area.weathers[0].replace(/　/g, ' ')
                                });
                            }
                        }

                        // --- Weekly Forecast (7 Days) ---
                        // Usually forecastData[1] contains the weekly forecast
                        if (forecastData.length > 1) {
                            const weekly = forecastData[1];
                            const timeDef = weekly.timeSeries[0].timeDefines; // Array of dates
                            const weatherArea = weekly.timeSeries[0].areas[0]; // Weather codes
                            const tempArea = weekly.timeSeries[1].areas[0]; // min/max temps

                            if (timeDef && weatherArea && tempArea) {
                                const parsedWeekly: DailyForecast[] = [];

                                // Weekly temps are staggered, tempsMin/tempsMax usually start from index 1 or have empty strings for today if today is almost over
                                // We iterate through timeDef (dates)
                                for (let i = 0; i < timeDef.length; i++) {
                                    // Parse ISO string to short date (e.g. 2/22)
                                    const dateObj = new Date(timeDef[i]);
                                    const shortDate = `${dateObj.getMonth() + 1}/${dateObj.getDate()}`;

                                    const weatherCode = weatherArea.weatherCodes ? weatherArea.weatherCodes[i] : 'unknown';

                                    // tempsMin and Max array length might differ or be empty for index 0
                                    let minTemp = "";
                                    let maxTemp = "";

                                    if (tempArea.tempsMin && tempArea.tempsMin.length > i) {
                                        minTemp = tempArea.tempsMin[i] !== "" ? tempArea.tempsMin[i] : "-";
                                    }
                                    if (tempArea.tempsMax && tempArea.tempsMax.length > i) {
                                        maxTemp = tempArea.tempsMax[i] !== "" ? tempArea.tempsMax[i] : "-";
                                    }

                                    parsedWeekly.push({
                                        date: shortDate,
                                        weatherCode: weatherCode,
                                        minTemp,
                                        maxTemp
                                    });
                                }
                                setWeeklyForecast(parsedWeekly);
                            }
                        }
                    }
                }
            } catch (fcErr) {
                console.error('Error fetching weather forecast:', fcErr);
            }

        } catch (err: any) {
            console.error('Error fetching disaster alerts/weather:', err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    }, [currentLocation.latitude, currentLocation.longitude]);

    useEffect(() => {
        checkAlerts();

        // Poll every 5 minutes
        const interval = setInterval(checkAlerts, 5 * 60 * 1000);
        return () => clearInterval(interval);
    }, [checkAlerts]);

    return {
        alerts,
        forecast,
        weeklyForecast,
        locationName,
        loading,
        error,
        refetch: checkAlerts
    };
}

import { useState, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/components/Auth/AuthProvider';

export type FamilyGroup = {
    id: string;
    name: string;
    invite_code: string;
    created_at: string;
};

export type GroupMember = {
    group_id: string;
    user_id: string;
    role: 'admin' | 'member';
    joined_at: string;
    users?: {
        display_name: string | null;
        avatar_url: string | null;
    };
};

export function useFamilyGroup() {
    const { user } = useAuth();
    const [currentGroup, setCurrentGroup] = useState<FamilyGroup | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // DEV MODE CHECK
    const isDevMode = typeof window !== 'undefined' && localStorage.getItem('dev_mock_session') === 'true';

    // Fetch the user's current group
    const fetchGroup = useCallback(async () => {
        if (!user) return;
        setLoading(true);
        setError(null);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            setTimeout(() => {
                const mockGroupId = localStorage.getItem('dev_mock_group_id');
                if (mockGroupId) {
                    setCurrentGroup({
                        id: mockGroupId,
                        name: 'テスト家族',
                        invite_code: 'TEST12',
                        created_at: new Date().toISOString()
                    });
                    setMembers([
                        {
                            group_id: mockGroupId,
                            user_id: user.id,
                            role: 'admin',
                            joined_at: new Date().toISOString(),
                            users: { display_name: 'テストパパ', avatar_url: null }
                        }
                    ]);
                } else {
                    setCurrentGroup(null);
                    setMembers([]);
                }
                setLoading(false);
            }, 500);
            return;
        }
        // ------------------------

        try {
            // 1. Find which group the user belongs to
            const { data: memberData, error: memberErr } = await supabase
                .from('group_members')
                .select('group_id')
                .eq('user_id', user.id)
                .maybeSingle(); // User can only be in one group for now

            if (memberErr) throw memberErr;

            if (memberData) {
                // 2. Fetch group details
                const { data: groupData, error: groupErr } = await supabase
                    .from('family_groups')
                    .select('*')
                    .eq('id', memberData.group_id)
                    .single();

                if (groupErr) throw groupErr;
                setCurrentGroup(groupData as FamilyGroup);

                // 3. Fetch all members with their profiles (join on users table)
                const { data: allMembers, error: allMembersErr } = await supabase
                    .from('group_members')
                    .select(`
            *,
            users (
              display_name,
              avatar_url
            )
          `)
                    .eq('group_id', memberData.group_id);

                if (allMembersErr) throw allMembersErr;
                setMembers(allMembers as unknown as GroupMember[]);
            } else {
                setCurrentGroup(null);
                setMembers([]);
            }
        } catch (err: any) {
            console.error('Error fetching group:', err);
            setError(err.message || 'グループ情報の取得に失敗しました');
        } finally {
            setLoading(false);
        }
    }, [user, isDevMode]);

    // Create a new group
    const createGroup = async (groupName: string) => {
        if (!user) return null;
        setLoading(true);
        setError(null);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            return new Promise<FamilyGroup | null>((resolve) => {
                setTimeout(() => {
                    localStorage.setItem('dev_mock_group_id', 'mock-group-123');
                    fetchGroup(); // Refresh state
                    resolve({ id: 'mock-group-123', name: groupName, invite_code: 'TEST12', created_at: new Date().toISOString() });
                }, 800);
            });
        }
        // ------------------------

        try {
            // 1. Insert into family_groups
            // The DB trigger or server logic usually generates the short invite_code,
            // but if we are doing it client side for simplicity:
            const inviteCode = Math.random().toString(36).substring(2, 8).toUpperCase();

            const { data: newGroup, error: insertErr } = await supabase
                .from('family_groups')
                .insert({ name: groupName, invite_code: inviteCode })
                .select()
                .single();

            if (insertErr) throw insertErr;

            // 2. Add current user as admin
            const { error: memberErr } = await supabase
                .from('group_members')
                .insert({
                    group_id: newGroup.id,
                    user_id: user.id,
                    role: 'admin'
                });

            if (memberErr) throw memberErr;

            // Refresh state
            await fetchGroup();
            return newGroup as FamilyGroup;
        } catch (err: any) {
            console.error('Error creating group:', err);
            setError(err.message || 'グループの作成に失敗しました');
            setLoading(false);
            return null;
        }
    };

    // Join an existing group using invite code
    const joinGroup = async (inviteCode: string) => {
        if (!user) return false;
        setLoading(true);
        setError(null);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            return new Promise<boolean>((resolve) => {
                setTimeout(() => {
                    if (inviteCode === 'TEST12') {
                        localStorage.setItem('dev_mock_group_id', 'mock-group-123');
                        fetchGroup();
                        resolve(true);
                    } else {
                        setError('無効な招待コードです (DevMode: TEST12 を使用してください)');
                        setLoading(false);
                        resolve(false);
                    }
                }, 800);
            });
        }
        // ------------------------

        try {
            // 1. Find the group by invite code
            const upperCode = inviteCode.toUpperCase().trim();
            const { data: groupData, error: groupErr } = await supabase
                .from('family_groups')
                .select('id')
                .eq('invite_code', upperCode)
                .maybeSingle();

            if (groupErr) throw groupErr;
            if (!groupData) {
                throw new Error('無効な招待コードです。入力内容を確認してください。');
            }

            // 2. Add user to the group
            const { error: memberErr } = await supabase
                .from('group_members')
                .insert({
                    group_id: groupData.id,
                    user_id: user.id,
                    role: 'member'
                });

            if (memberErr) {
                // Handle unique constraint violation (already joined)
                if (memberErr.code === '23505') {
                    throw new Error('すでにこのグループに参加しています。');
                }
                throw memberErr;
            }

            // Refresh state
            await fetchGroup();
            return true;
        } catch (err: any) {
            console.error('Error joining group:', err);
            setError(err.message || 'グループへの参加に失敗しました');
            setLoading(false);
            return false;
        }
    };

    // Leave current group
    const leaveGroup = async () => {
        if (!user || !currentGroup) return false;
        setLoading(true);
        setError(null);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            return new Promise<boolean>((resolve) => {
                setTimeout(() => {
                    localStorage.removeItem('dev_mock_group_id');
                    setCurrentGroup(null);
                    setMembers([]);
                    setLoading(false);
                    resolve(true);
                }, 500);
            });
        }
        // ------------------------

        try {
            const { error: leaveErr } = await supabase
                .from('group_members')
                .delete()
                .eq('group_id', currentGroup.id)
                .eq('user_id', user.id);

            if (leaveErr) throw leaveErr;

            setCurrentGroup(null);
            setMembers([]);
            return true;
        } catch (err: any) {
            console.error('Error leaving group:', err);
            setError(err.message || 'グループの退出に失敗しました');
            setLoading(false);
            return false;
        }
    };

    return {
        currentGroup,
        members,
        loading,
        error,
        fetchGroup,
        createGroup,
        joinGroup,
        leaveGroup
    };
}

import { useState, useEffect, useCallback } from 'react';
import { useGeolocation } from 'react-use';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/components/Auth/AuthProvider';

export interface UserLocation {
    id: string; // user_id
    name: string; // display_name
    lat: number;
    lng: number;
    updatedAt: number;
    status: 'safe' | 'danger' | 'unknown';
    message?: string;
}

export function useFamilyLocation() {
    const { user } = useAuth();
    const currentLocation = useGeolocation({
        enableHighAccuracy: true,
        timeout: 30000,
        maximumAge: 300000
    });

    const [familyLocations, setFamilyLocations] = useState<UserLocation[]>([]);
    const [loading, setLoading] = useState(false);

    // Handle DevMode
    const isDevMode = typeof window !== 'undefined' && localStorage.getItem('dev_mock_session') === 'true';

    const fetchLocations = useCallback(async () => {
        if (!user) return;
        setLoading(true);

        // --- DEV MODE BYPASS ---
        if (isDevMode) {
            const hasMockGroup = localStorage.getItem('dev_mock_group_id');
            if (hasMockGroup) {
                const savedStatus = localStorage.getItem('dev_mock_status') as 'safe' | 'danger' | 'unknown' | null;
                const savedMessage = localStorage.getItem('dev_mock_message');
                const savedUpdatedAt = localStorage.getItem('dev_mock_updated_at');

                // Mock data simulating a fetched group
                setFamilyLocations([
                    {
                        id: user.id,
                        name: 'あなた',
                        lat: currentLocation.latitude || 35.6812, // default to Tokyo if unknown
                        lng: currentLocation.longitude || 139.7671,
                        updatedAt: savedUpdatedAt ? parseInt(savedUpdatedAt) : Date.now(),
                        status: savedStatus || 'safe',
                        message: savedMessage !== null ? savedMessage : 'DevModeのテスト報告です'
                    },
                    {
                        id: 'mock-family-uuid',
                        name: '母',
                        lat: (currentLocation.latitude || 35.6812) + 0.002,
                        lng: (currentLocation.longitude || 139.7671) + 0.002,
                        updatedAt: Date.now() - 3600000, // 1 hour ago
                        status: 'unknown',
                        message: '買い物に行きます'
                    }
                ]);
            } else {
                setFamilyLocations([]);
            }
            setLoading(false);
            return;
        }
        // ------------------------

        try {
            // Get the user's group, then fetch members, then fetch their status
            // A more optimized query using left joins in Supabase:
            const { data, error } = await supabase
                .rpc('get_family_safety_status', { p_user_id: user.id });

            // If RPC doesn't exist (which we haven't created), we do it in a few steps:
            // 1. Get user's group
            const { data: memberData } = await supabase
                .from('group_members')
                .select('group_id')
                .eq('user_id', user.id)
                .maybeSingle();

            if (!memberData) {
                setFamilyLocations([]);
                setLoading(false);
                return;
            }

            // 2. Fetch all members of this group
            const { data: groupMembers, error: gmErr } = await supabase
                .from('group_members')
                .select('user_id')
                .eq('group_id', memberData.group_id);

            if (gmErr || !groupMembers) {
                setFamilyLocations([]);
                return;
            }

            const memberIds = groupMembers.map(m => m.user_id);

            const { data: finalData, error: finalErr } = await supabase
                .from('safety_status')
                .select(`
                    user_id,
                    status,
                    message,
                    latitude,
                    longitude,
                    updated_at,
                    users ( display_name )
                `)
                .in('user_id', memberIds);

            if (finalErr) throw finalErr;

            if (finalData) {
                const formatted: UserLocation[] = finalData.map((row: any) => ({
                    id: row.user_id,
                    name: row.users?.display_name || '名前未設定',
                    lat: row.latitude || 0,
                    lng: row.longitude || 0,
                    updatedAt: new Date(row.updated_at).getTime(),
                    status: row.status,
                    message: row.message || undefined
                }));

                setFamilyLocations(formatted);
            }
        } catch (err) {
            console.error('Error fetching family locations:', err);
        } finally {
            setLoading(false);
        }
    }, [user, currentLocation.latitude, currentLocation.longitude, isDevMode]);

    useEffect(() => {
        fetchLocations();

        // Listen for dev mock updates
        if (typeof window !== 'undefined') {
            const handleUpdate = () => fetchLocations();
            window.addEventListener('dev_mock_status_update', handleUpdate);
            return () => window.removeEventListener('dev_mock_status_update', handleUpdate);
        }
    }, [fetchLocations]);

    return {
        currentLocation,
        familyLocations,
        loading,
        refetch: fetchLocations
    };
}

